package com.naturalstreaming;
import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@RestController @ConditionalOnProperty(name="ns.role",havingValue="admin") public class AdminApi {
 final Auth auth;final Catalog catalog;final JdbcTemplate db;final ThemeValidator validator;
 AdminApi(Auth a,Catalog c,JdbcTemplate d,ThemeValidator v){auth=a;catalog=c;db=d;validator=v;}
 void ids(String theme,String version){if(!ThemeValidator.id(theme)||!ThemeValidator.id(version))throw ApiError.fail(400,"invalid_id");}
 void audit(String actor,String action,String target){db.update("INSERT INTO audit_log(actor,action,target) VALUES(?,?,?)",actor,action,target);}
 @GetMapping("/v1/admin/audit") Map<?,?> auditEvents(HttpServletRequest r){auth.service(r,"publish");return Map.of("events",db.queryForList("SELECT id,actor,action,target,created_at FROM audit_log ORDER BY id DESC LIMIT 100"));}
 @PostMapping("/v1/admin/accounts") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<?,?> account(HttpServletRequest r,@RequestBody Map<String,String>b){String actor=auth.service(r,"accounts"),name=Json.text(b,"username"),pass=Json.text(b,"password");if(!name.matches("[A-Za-z0-9_-]{3,80}")||pass.length()<12||pass.length()>72)throw ApiError.fail(400,"invalid_account");catalog.lockClock();if(db.queryForObject("SELECT COUNT(*) FROM account WHERE username=?",Integer.class,name)>0)throw ApiError.fail(409,"account_exists");db.update("INSERT INTO account(username,password_hash) VALUES(?,?)",name,new BCryptPasswordEncoder().encode(pass));long id=db.queryForObject("SELECT id FROM account WHERE username=?",Long.class,name);audit(actor,"account_create",Long.toString(id));return Map.of("id",id,"username",name);}
 @GetMapping("/v1/admin/accounts") Map<?,?> accounts(HttpServletRequest r){auth.service(r,"accounts");return Map.of("accounts",db.queryForList("SELECT id,username,enabled,active_device FROM account ORDER BY id"));}
 @GetMapping("/v1/admin/accounts/{id}/themes") Map<?,?> accountThemes(HttpServletRequest r,@PathVariable long id){auth.service(r,"accounts");if(db.queryForObject("SELECT COUNT(*) FROM account WHERE id=?",Integer.class,id)!=1)throw ApiError.fail(404,"account_missing");return Map.of("accountId",id,"entitlements",db.queryForList("SELECT theme_id,allowed FROM entitlement WHERE account_id=? ORDER BY theme_id",id));}
 @PutMapping("/v1/admin/accounts/{id}") @Transactional public Map<?,?> accountUpdate(HttpServletRequest r,@PathVariable long id,@RequestBody Map<String,Object>b){String actor=auth.service(r,"accounts");catalog.lockClock();if(db.queryForObject("SELECT COUNT(*) FROM account WHERE id=?",Integer.class,id)!=1)throw ApiError.fail(404,"account_missing");if(b.get("enabled") instanceof Boolean enabled)db.update("UPDATE account SET enabled=?,epoch=epoch+1 WHERE id=?",enabled,id);if(b.containsKey("password")){String pass=Json.text(b,"password");if(pass.length()<12||pass.length()>72)throw ApiError.fail(400,"invalid_password");db.update("UPDATE account SET password_hash=?,epoch=epoch+1 WHERE id=?",new BCryptPasswordEncoder().encode(pass),id);}audit(actor,"account_update",Long.toString(id));return Map.of("status","updated");}
 @PutMapping("/v1/admin/accounts/{id}/themes/{theme}") @Transactional public Map<?,?> grant(HttpServletRequest r,@PathVariable long id,@PathVariable String theme,@RequestBody Map<String,Object>b){String actor=auth.service(r,"accounts");if(!(b.get("allowed") instanceof Boolean allowed))throw ApiError.fail(400,"invalid_request");catalog.lockClock();if(db.queryForObject("SELECT COUNT(*) FROM account WHERE id=?",Integer.class,id)!=1||db.queryForObject("SELECT COUNT(*) FROM theme WHERE id=?",Integer.class,theme)!=1)throw ApiError.fail(404,"account_or_theme_missing");db.update("INSERT INTO entitlement(account_id,theme_id,allowed) VALUES(?,?,?) ON DUPLICATE KEY UPDATE allowed=?",id,theme,allowed,allowed);catalog.event(theme,id);audit(actor,allowed?"grant":"revoke",id+":"+theme);return Map.of("allowed",allowed);}
 @PostMapping("/v1/admin/credentials") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<?,?> credential(HttpServletRequest r,@RequestBody Map<String,Object>b){String actor=auth.service(r,"credentials");String id=Json.text(b,"id");if(!ThemeValidator.id(id))throw ApiError.fail(400,"invalid_id");var scopes=(List<String>)b.get("scopes");if(scopes==null||scopes.isEmpty()||!Set.of("upload","publish","accounts","credentials").containsAll(scopes))throw ApiError.fail(400,"invalid_scope");String token=Auth.random();try{db.update("INSERT INTO service_credential(id,token_hash,scopes) VALUES(?,?,?)",id,Auth.hash(token),String.join(",",new java.util.TreeSet<>(scopes)));}catch(org.springframework.dao.DuplicateKeyException e){throw ApiError.fail(409,"credential_exists");}audit(actor,"credential_create",id);return Map.of("id",id,"token",token,"scopes",scopes);}
 @GetMapping("/v1/admin/credentials") Map<?,?> credentials(HttpServletRequest r){auth.service(r,"credentials");return Map.of("credentials",db.queryForList("SELECT id,scopes,revoked,expires_at FROM service_credential ORDER BY id"));}
 @DeleteMapping("/v1/admin/credentials/{id}") @Transactional public Map<?,?> revokeCredential(HttpServletRequest r,@PathVariable String id){String actor=auth.service(r,"credentials");if(actor.equals(id))throw ApiError.fail(409,"cannot_revoke_self");if(db.queryForObject("SELECT COUNT(*) FROM service_credential WHERE id=?",Integer.class,id)==0)throw ApiError.fail(404,"credential_missing");db.update("UPDATE service_credential SET revoked=TRUE WHERE id=?",id);audit(actor,"credential_revoke",id);return Map.of("status","revoked");}
 @GetMapping("/v1/admin/themes") Map<?,?> themes(HttpServletRequest r){auth.service(r,"upload");return Map.of("themes",db.queryForList("SELECT id,current_version,listed FROM theme ORDER BY id"));}
 @GetMapping("/v1/admin/themes/{theme}/versions") Map<?,?> versions(HttpServletRequest r,@PathVariable String theme){auth.service(r,"upload");return Map.of("versions",db.queryForList("SELECT version,state,revision,validated_revision,validation_json,created_at,published_at FROM theme_version WHERE theme_id=? ORDER BY created_at",theme));}
 @GetMapping("/v1/admin/themes/{theme}/versions/{version}") Map<?,?> version(HttpServletRequest r,@PathVariable String theme,@PathVariable String version){auth.service(r,"upload");return catalog.document(catalog.version(theme,version,false));}
 @PutMapping("/v1/admin/themes/{theme}/versions/{version}") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<?,?> draft(HttpServletRequest r,@PathVariable String theme,@PathVariable String version,@RequestBody Map<String,Object>b){String actor=auth.service(r,"upload");ids(theme,version);if(!(b.get("scene") instanceof Map)||!(b.get("manifest") instanceof Map)||!(b.get("license") instanceof Map)||Json.write(b).length()>500000)throw ApiError.fail(400,"invalid_request");catalog.lockClock();db.update("INSERT IGNORE INTO theme(id) VALUES(?)",theme);var old=db.queryForList("SELECT * FROM theme_version WHERE theme_id=? AND version=? FOR UPDATE",theme,version);long rev=1;
  if(!old.isEmpty()){var row=old.getFirst();if("published".equals(row.get("state")))throw ApiError.fail(409,"version_immutable");long existing=((Number)row.get("revision")).longValue();if(!(b.get("revision") instanceof Number n)||n.longValue()!=existing)throw ApiError.fail(409,"revision_conflict",Map.of("revision",existing));rev=existing+1;db.update("UPDATE theme_version SET scene_json=?,manifest_json=?,license_json=?,revision=?,validated_revision=NULL,validation_json=NULL WHERE theme_id=? AND version=?",Json.write(b.get("scene")),Json.write(b.get("manifest")),Json.write(b.get("license")),rev,theme,version);
  }else db.update("INSERT INTO theme_version(theme_id,version,scene_json,manifest_json,license_json) VALUES(?,?,?,?,?)",theme,version,Json.write(b.get("scene")),Json.write(b.get("manifest")),Json.write(b.get("license")));
  audit(actor,"draft_save",theme+":"+version);return Map.of("themeId",theme,"version",version,"revision",rev,"state","draft");
 }
 @PostMapping("/v1/admin/themes/{theme}/versions/{version}/validate") @Transactional public Map<?,?> validate(HttpServletRequest r,@PathVariable String theme,@PathVariable String version,@RequestBody(required=false) Map<String,Object> expected){auth.service(r,"upload");catalog.lockClock();var v=catalog.lockVersion(theme,version);if(expected!=null&&expected.containsKey("revision")&&Json.num(expected.get("revision"))!=((Number)v.get("revision")).doubleValue())throw ApiError.fail(409,"revision_conflict",Map.of("revision",v.get("revision")));if("published".equals(v.get("state")))return Map.of("valid",true,"revision",v.get("revision"));Map<String,Object> body=Map.of("scene",Json.read((String)v.get("scene_json")),"manifest",Json.read((String)v.get("manifest_json")),"license",Json.read((String)v.get("license_json")));
  try{validator.validate(theme,body);}catch(ApiError e){db.update("UPDATE theme_version SET validated_revision=NULL,validation_json=? WHERE theme_id=? AND version=?",Json.write(e.details),theme,version);return Map.of("valid",false,"revision",v.get("revision"),"errors",e.details);}
  db.update("UPDATE theme_version SET validated_revision=revision,validation_json='[]' WHERE theme_id=? AND version=?",theme,version);return Map.of("valid",true,"revision",v.get("revision"),"errors",List.of());
 }
 @PostMapping("/v1/admin/themes/{theme}/versions/{version}/publish") @Transactional public Map<?,?> publish(HttpServletRequest r,@PathVariable String theme,@PathVariable String version,@RequestBody(required=false) Map<String,Object> expected){String actor=auth.service(r,"publish");catalog.lockClock();var v=catalog.lockVersion(theme,version);if(expected!=null&&expected.containsKey("revision")&&Json.num(expected.get("revision"))!=((Number)v.get("revision")).doubleValue())throw ApiError.fail(409,"revision_conflict",Map.of("revision",v.get("revision")));if(v.get("validated_revision")==null||((Number)v.get("validated_revision")).longValue()!=((Number)v.get("revision")).longValue())throw ApiError.fail(409,"validation_required");
  db.update("UPDATE theme_version SET state='published',published_at=COALESCE(published_at,UTC_TIMESTAMP()) WHERE theme_id=? AND version=?",theme,version);db.update("UPDATE theme SET current_version=?,listed=TRUE WHERE id=?",version,theme);catalog.event(theme,null);audit(actor,"publish",theme+":"+version);return Map.of("themeId",theme,"version",version,"state","published");
 }
 @PostMapping("/v1/admin/themes/{theme}/unpublish") @Transactional public Map<?,?> unpublish(HttpServletRequest r,@PathVariable String theme){String actor=auth.service(r,"publish");catalog.lockClock();if(db.update("UPDATE theme SET listed=FALSE WHERE id=?",theme)==0)throw ApiError.fail(404,"theme_missing");catalog.event(theme,null);audit(actor,"unpublish",theme);return Map.of("status","unpublished");}
 @PostMapping("/v1/admin/themes/{theme}/rollback") @Transactional public Map<?,?> rollback(HttpServletRequest r,@PathVariable String theme,@RequestBody Map<String,String>b){String actor=auth.service(r,"publish");String version=Json.text(b,"version");catalog.lockClock();catalog.version(theme,version,true);db.update("UPDATE theme SET current_version=?,listed=TRUE WHERE id=?",version,theme);catalog.event(theme,null);audit(actor,"rollback",theme+":"+version);return Map.of("themeId",theme,"version",version);}
}
